// Clint envia: { clint_id, belle_id, nome, telefone, protocolo, servicos, valor, forma_pagamento, vendedor }
const body = $input.item.json.body || $input.item.json;

const hoje = new Date();
const fmt = (d) => `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;

return {
  json: {
    clint_id:       body.clint_id,
    clint_card_id:  body.clint_card_id || body.card_id,
    belle_id:       body.belle_id,
    nome:           body.nome,
    telefone:       body.telefone,
    protocolo:      body.protocolo || body.plano || '',
    servicos:       body.servicos || [],
    valor:          body.valor || 0,
    forma_pagamento: body.forma_pagamento || 'Dinheiro',
    vendedor:       body.vendedor || '',
    data_venda:     fmt(hoje),
    data_venda_iso: hoje.toISOString().split('T')[0]
  }
};

